sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var status = current.task_status.toString();

    if ((status == 'Assigned' || status == 'In Progress') &&
        current.assigned_to.nil()) {

        gs.addErrorMessage(
            'Assigned To is required when the Clinical Task status is Assigned or In Progress.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
